update public.spell_catalog set name_ru='Фантомная сила', casting_time='Действие', spell_range='60 футов', area='1 видимое существо; иллюзия до куба 10 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='кусочек шерсти', check_type='Спасбросок Интеллекта; изучение: Интеллект (Расследование) против Сл спасброска заклинаний', damage='До 2к8 психического урона за ход от опасной иллюзии', effect_summary='Создаёшь в разуме цели иллюзию предмета, существа или явления, которую воспринимает только она. При провале спасброска цель считает иллюзию реальной и сама объясняет любые несостыковки. Опасная иллюзия может наносить психический урон.', upcast='', notes='Цель может действием Изучения распознать иллюзию и закончить заклинание.', author_description='Вкладываешь человеку в голову проблему и позволяешь его собственному мозгу дорисовать детали. Эффективно и пугающе экономно.', author_comment='Лучшие иллюзии не убеждают тебя. Они заставляют тебя убеждать себя самому.' where slug='phantasmal-force';
update public.spell_catalog set name_ru='Молитва об исцелении', casting_time='Действие', spell_range='30 футов', area='До 5 существ, остающихся в пределах дистанции всё время накладывания', duration='Мгновенно', components=array['В'], material=null, check_type='', damage='Лечение: 2к8 HP', effect_summary='До пяти существ получают преимущества короткого отдыха и восстанавливают 2к8 HP.', upcast='+1к8 лечения за каждый уровень ячейки выше 2.', notes='Одно и то же существо не может получить эффект снова, пока не завершит долгий отдых.', author_description='Жрец устраивает короткий отдых по ускоренной программе и ещё лечит. Ненавижу, когда у них есть объективно хорошие аргументы.', author_comment='Пять человек восстановились. Жрец теперь будет рассказывать об этом до следующего долгого отдыха.' where slug='prayer-of-healing';
update public.spell_catalog set name_ru='Защита от яда', casting_time='Действие', spell_range='Касание', area='1 существо', duration='1 час', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Снимает состояние Отравление. На час цель получает преимущество на спасброски против Отравления и сопротивление урону ядом.', upcast='', notes='Не требует концентрации.', author_description='Сначала вытаскиваешь яд из человека, потом делаешь следующий яд менее убедительным. Практично, скучно и поэтому прекрасно.', author_comment='Если после этого ты снова добровольно пьёшь подозрительный напиток — магия уже не виновата.' where slug='protection-from-poison';
update public.spell_catalog set name_ru='Луч ослабления', casting_time='Действие', spell_range='60 футов', area='1 существо', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Телосложения; повтор в конце каждого хода при провале', damage='При провале: −1к8 ко всем броскам урона', effect_summary='При успехе цель получает помеху только на следующий бросок атаки до начала твоего следующего хода. При провале на время действия получает помеху на проверки к20, основанные на Силе, и вычитает 1к8 из всех бросков урона.', upcast='', notes='При провале цель повторяет спасбросок в конце каждого своего хода и заканчивает эффект при успехе.', author_description='Не убивает врага. Просто заставляет его внезапно почувствовать себя намного менее героически. Иногда это даже обиднее.', author_comment='Когда огромный варвар начинает бить как уставший бухгалтер, понимаешь ценность некромантии.' where slug='ray-of-enfeeblement';
update public.spell_catalog set name_ru='Фокус с верёвкой', casting_time='Действие', spell_range='Касание', area='1 верёвка; внепространственное убежище до 8 средних или меньших существ', duration='1 час', components=array['В','С','М'], material='отрезок верёвки', check_type='', damage='', effect_summary='Конец верёвки поднимается вверх и открывает невидимый портал в внепространственное помещение. Внутри помещается до восьми существ Среднего размера или меньше. Через портал нельзя атаковать, колдовать или проводить другие эффекты внутрь и наружу.', upcast='', notes='Существа внутри видят наружу. Всё содержимое выпадает, когда заклинание заканчивается.', author_description='Поднимаешься по верёвке в карманное убежище, где час никто не может тебя достать. Волшебники называют это магией пространства. Я — грамотно организованным бегством.', author_comment='Если вся партия молча полезла за тобой, значит план действительно был плох.' where slug='rope-trick';
update public.spell_catalog set name_ru='Палящий луч', casting_time='Действие', spell_range='120 футов', area='До 3 лучей по одной или нескольким целям', duration='Мгновенно', components=array['В','С'], material=null, check_type='Отдельная дальняя атака заклинанием для каждого луча', damage='2к6 огнём за каждый попавший луч', effect_summary='Создаёшь три огненных луча. Каждый можно направить в одну или разные цели; для каждого совершается отдельная атака.', upcast='+1 луч за каждый уровень ячейки выше 2.', notes='Урон каждого луча считается отдельно.', author_description='Три попытки поджечь кого-нибудь вместо одной. Волшебники называют это надёжностью системы.', author_comment='Если промахнулся всеми тремя, не переживай. Воин уже всё видел.' where slug='scorching-ray';
update public.spell_catalog set name_ru='Видение невидимого', casting_time='Действие', spell_range='На себя', area='На себя', duration='1 час', components=array['В','С','М'], material='щепотка талька', check_type='', damage='', effect_summary='На час видишь Невидимых существ и объекты как обычные, а также видишь Эфирный план. Существа и предметы там выглядят призрачными.', upcast='', notes='Не требует концентрации.', author_description='На час прекращаешь участвовать в детской игре «я невидимый, значит меня нет». Полезно против магов и плутов, то есть против двух пород лжецов.', author_comment='Невидимость перестаёт работать. Плут внезапно вспоминает, что у него есть ноги.' where slug='see-invisibility';
update public.spell_catalog set name_ru='Дребезги', casting_time='Действие', spell_range='60 футов', area='Сфера радиусом 10 футов', duration='Мгновенно', components=array['В','С','М'], material='осколок слюды', check_type='Спасбросок Телосложения; Конструкты с помехой', damage='3к8 звукового урона; половина при успехе', effect_summary='В точке раздаётся разрушительный звук. Все существа в сфере делают спасбросок Телосложения; немагические непереносимые предметы в области тоже получают урон.', upcast='+1к8 урона за каждый уровень ячейки выше 2.', notes='Конструкты совершают спасбросок с помехой.', author_description='Кричишь магией так громко, что трескаются вещи и люди. Барды обычно пытаются добиться того же без ячейки.', author_comment='После этого заклинания слово «тихо» обычно уже не имеет смысла.' where slug='shatter';
update public.spell_catalog set name_ru='Сияющая кара', casting_time='Бонусное действие, сразу после попадания оружием ближнего боя или безоружным ударом', spell_range='На себя', area='Цель только что совершённого попадания', duration='Концентрация, до 1 минуты', components=array['В'], material=null, check_type='', damage='Дополнительно 2к6 излучением', effect_summary='После попадания добавляешь урон излучением. До конца заклинания цель светится ярким светом на 5 футов, атаки по ней совершаются с преимуществом, а Невидимость не даёт ей преимуществ.', upcast='+1к6 урона за каждый уровень ячейки выше 2.', notes='Можно применить только сразу после подходящего попадания.', author_description='Паладин бьёт человека и делает его светящимся, чтобы всем остальным было удобнее бить дальше. Наконец проповедь, которую я понимаю.', author_comment='Очень духовно. Особенно та часть, где вся группа получает преимущество добивать цель.' where slug='shining-smite';
update public.spell_catalog set name_ru='Тишина', casting_time='Действие', spell_range='120 футов', area='Сфера радиусом 20 футов', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='', damage='', effect_summary='В области нельзя создавать или передавать звук. Полностью находящиеся внутри существа Оглохшие, а существа и предметы получают иммунитет к звуковому урону. Заклинания с вербальным компонентом внутри области сотворить нельзя.', upcast='', notes='Ритуал. Звук не проходит через границу сферы.', author_description='На двадцать футов мир наконец становится терпимым. Особенно если рядом бард.', author_comment='Редкий случай, когда магия улучшает жизнь вообще всех вокруг.' where slug='silence';
update public.spell_catalog set name_ru='Паучье лазание', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='капля битума и паук', check_type='', damage='', effect_summary='Цель получает скорость лазания, равную её обычной Скорости, и может свободно перемещаться по стенам и потолкам, не занимая руки.', upcast='+1 цель за каждый уровень ячейки выше 2.', notes='Требует концентрации.', author_description='Позволяет ходить по стенам и потолку. Отличный способ убедиться, что у трактирщика больше никогда не будет вопросов к вашей группе.', author_comment='Если друид начал ползать по потолку, не гладь его. Мы это уже обсуждали.' where slug='spider-climb';
update public.spell_catalog set name_ru='Рост шипов', casting_time='Действие', spell_range='150 футов', area='Сфера радиусом 20 футов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='семь шипов', check_type='Если не видел появление: Мудрость (Восприятие или Выживание) против Сл спасброска заклинаний для распознавания опасности', damage='2к4 колющего урона за каждые 5 футов движения', effect_summary='Земля покрывается скрытыми шипами и становится труднопроходимой. Каждые 5 футов движения внутри наносят 2к4 колющего урона.', upcast='', notes='Территория маскируется под естественную. Существо, не видевшее наложение, должно специально искать опасность, чтобы заметить её заранее.', author_description='Друид превращает землю в ковёр из ножей и всё ещё будет рассказывать тебе о гармонии с природой.', author_comment='Природа прекрасна. Особенно когда каждый шаг стоит 2к4.' where slug='spike-growth';
update public.spell_catalog set name_ru='Духовное оружие', casting_time='Бонусное действие', spell_range='60 футов', area='Спектральное оружие в выбранной точке', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Рукопашная атака заклинанием', damage='1к8 + модификатор характеристики заклинаний силовым уроном', effect_summary='Создаёшь спектральное оружие и сразу можешь атаковать цель в 5 футах от него. В последующие ходы бонусным действием можно передвигать оружие до 20 футов и атаковать снова.', upcast='+1к8 урона за каждый уровень ячейки выше 2.', notes='Требует концентрации.', author_description='Жрец создаёт оружие, которое само летает и бьёт людей. Наконец-то молитва, где результат можно измерить синяками.', author_comment='Даже духовное оружие стоит впереди жреца. Символично.' where slug='spiritual-weapon';
update public.spell_catalog set name_ru='Внушение', casting_time='Действие', spell_range='30 футов', area='1 существо, которое слышит и понимает тебя', duration='Концентрация, до 8 часов', components=array['В','М'], material='капля мёда', check_type='Спасбросок Мудрости', damage='', effect_summary='Формулируешь выполнимое внушение до 25 слов. При провале цель становится Очарованной и старается выполнить указание до завершения задачи или окончания заклинания.', upcast='', notes='Нельзя предлагать очевидно вредное для цели или её союзников действие. Эффект заканчивается, если ты или союзники наносите цели урон.', author_description='Говоришь человеку идею так убедительно, что он восемь часов считает её своей проблемой. Жрецы делают примерно то же самое без ячеек.', author_comment='Если тебе нужно больше 25 слов, чтобы объяснить план, возможно, план уже плохой.' where slug='suggestion';
update public.spell_catalog set name_ru='Оберегающая связь', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='1 час', components=array['В','С','М'], material='пара платиновых колец стоимостью 50+ зм каждое; оба участника носят их всё время', check_type='', damage='Цель получает сопротивление всему урону; такой же объём полученного ею урона наносится заклинателю', effect_summary='Связываешь себя с целью. Пока она в 60 футах, получает +1 к КД и спасброскам и сопротивление всему урону. Каждый раз, когда она получает урон, ты получаешь столько же.', upcast='', notes='Заканчивается, если ты падаешь до 0 HP, расстояние становится больше 60 футов или заклинание снова накладывают на одного из участников.', author_description='Делишь чужие раны пополам, только вторую половину забираешь себе. Романтично, пока кто-нибудь не встретит великана.', author_comment='Если жрец говорит «я разделю твою боль», впервые стоит уточнить буквально ли.' where slug='warding-bond';
update public.spell_catalog set name_ru='Паутина', casting_time='Действие', spell_range='60 футов', area='Куб 20 футов', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='кусочек паутины', check_type='Спасбросок Ловкости; освобождение: Сила (Атлетика) против Сл спасброска заклинаний', damage='Огонь: 2к4 существам, начинающим ход в горящем кубе паутины', effect_summary='Создаёт липкую паутину, которая является труднопроходимой местностью и слегка заслоняет область. Существо при первом входе за ход или начале хода делает спасбросок Ловкости, иначе становится Опутанным.', upcast='', notes='Паутина должна быть закреплена или лежать на поверхности, иначе схлопывается в начале следующего хода. Горюча: 5-футовый куб сгорает за 1 раунд.', author_description='Двадцать футов липкой мерзости, которая держит врагов, горит и портит мебель. Иногда волшебники действительно учатся у пауков правильным вещам.', author_comment='Если кто-то поджигает паутину, убедись, что это был план, а не очередной импульс волшебника.' where slug='web';
update public.spell_catalog set name_ru='Зона истины', casting_time='Действие', spell_range='60 футов', area='Сфера радиусом 15 футов', duration='10 минут', components=array['В','С'], material=null, check_type='Спасбросок Харизмы при первом входе за ход или начале хода', damage='', effect_summary='В области существо при провале спасброска не может сознательно произнести ложь. Заклинатель знает, кто преуспел и кто провалил спасбросок.', upcast='', notes='Цель знает об эффекте и может молчать, уклоняться от ответа или формулировать правдивые, но вводящие в заблуждение ответы.', author_description='Место, где нельзя сознательно лгать. Жрецы обычно начинают чувствовать себя заметно менее разговорчивыми.', author_comment='Не заставляет отвечать на вопрос. Потому что даже магия понимает ценность адвоката.' where slug='zone-of-truth';